use super::*;
use crate::{DslValue,Number,retained_clone::RetainedCloneSource};
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
#[test]fn actual_box_receiving_funds_real_backing_and_every_cancelled_partial_owner(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();for cut in row["cancelPrefixes"].as_array().unwrap().iter().map(|x|Some(x.as_u64().unwrap())).chain([None]){let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(DslValue::Number(Number::UInt(row["value"].as_u64().unwrap())),&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w,p,work,_,_|post(w.0,w.1,p,work))};let(mut receiver,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||<Box<u64> as NativeReceive<DslValue>>::receiver());assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(s["capacityBytes"].as_u64().unwrap()as usize,&mut callback);for at in 0..row["maximumTurns"].as_u64().unwrap(){if cut==Some(at)||receiver.output_ready(){break}let denied=receiver.advance(source.borrow(),&mut control,4096,RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,row["deniedWork"].as_u64().unwrap());assert_eq!(denied.result.unwrap().progress(),Default::default());let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,RetainedCloneGrant{maximum_items:1,..bank}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}
 if cut.is_none(){assert!(receiver.output_ready());let turn=receiver.take(RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();post(&mut bank,&mut fuel,p,work);assert_eq!(serde_json::to_value(*output).unwrap(),row["value"]);let mut owner=crate::retirement::controlled::ControlledRetirement::new(output).map_err(|(error,_)|error).unwrap();for _ in 0..row["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..bank}).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,owner.last_turn_work());}assert!(owner.terminal_is_empty());}
 receiver.begin_close();for _ in 0..row["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.close_step(RetainedCloneGrant{maximum_items:1,..bank}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}assert!(receiver.terminal_is_empty());drop(receiver);for _ in 0..row["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}let turn=source.close_step(RetainedCloneGrant{maximum_items:1,..bank});let p=turn.result.unwrap().progress();post(&mut bank,&mut fuel,p,turn.work);}assert!(source.terminal_is_empty());}}
